function getSeasonBaseFromPage(){var n;const s=document.querySelector(".sr-page"),a=(n=s==null?void 0:s.dataset)==null?void 0:n.season;return a?`/assets/data/stagione-regolare/${a}`:null}async function loadJson(s){const a=new URL(s,window.location.origin);a.searchParams.set("_",String(Date.now()));const n=await fetch(a.toString(),{cache:"no-store"});if(!n.ok)throw new Error(`Errore caricamento: ${s}`);return n.json()}function avatar(s,a="small"){return s.foto_url?`<img class="sr-avatar sr-avatar-${a}" src="${s.foto_url}" alt="${s.nome}">`:`
    <div class="sr-avatar sr-avatar-${a} sr-avatar-placeholder" style="background:${s.colore_avatar||"#5b4500"}">
      ${s.iniziale||s.nome.charAt(0)}
    </div>
  `}function conferenceLogo(s){return s.logo_url?`<img class="sr-conference-logo" src="${s.logo_url}" alt="${s.nome}">`:`
    <div class="sr-conference-logo sr-conference-logo-placeholder">
      ${s.nome_breve.charAt(0)}
    </div>
  `}function getStats(s,a){return{leader:s[0]?a[s[0].giocante_id]:null,giocanti:Object.keys(a).length}}async function loadConferenceData(s,a){const n=`${s}/${a}`,[e,o]=await Promise.all([loadJson(`${n}/giocanti.json`),loadJson(`${n}/classifica.json`)]),r=Object.fromEntries(e.map(t=>[t.id,t]));return{giocanti:e,classifica:o,giocantiMap:r}}function isConferenceCardAvailable({giocanti:s,classifica:a}){return Array.isArray(s)&&Array.isArray(a)&&s.length>0&&a.length>0}async function renderConferenceCards(s,a){return`
    <section class="sr-card sr-card-carousel">
      <div class="sr-section-title">
        <span>Seleziona conferenza</span>
        <strong>Campionato</strong>
      </div>

      <div class="sr-carousel" aria-label="Conferenze">
        <div class="sr-conference-grid">
          ${(await Promise.all(s.map(async e=>{try{const o=await loadConferenceData(a,e.id),{classifica:r,giocantiMap:t}=o,c=getStats(r,t);return{conferenza:e,stats:c,available:isConferenceCardAvailable(o)}}catch(o){return{conferenza:e,stats:{leader:null,giocanti:0},available:!1}}}))).map(({conferenza:e,stats:o,available:r})=>`
            <button class="sr-conference-card" data-conference="${e.id}" ${r?"":"disabled"}>
              ${conferenceLogo(e)}

              <div class="sr-conference-card-body">
                <h2>${e.nome_breve}</h2>
                <p>${e.area}</p>

                <div class="sr-conference-stats">
                  <span>${o.giocanti} giocanti</span>
                </div>

                <div class="sr-conference-leader">
                  <small>Leader</small>
                  <strong>${o.leader?o.leader.nome:"In attesa dati"}</strong>
                </div>
              </div>
            </button>
          `).join("")}
        </div>
      </div>
    </section>
  `}function renderPodio(s,a,n){const e=a.slice(0,3),o=[e[1],e[0],e[2]].filter(Boolean).filter(r=>n[r.giocante_id]);return`
    <section class="sr-card">
      <div class="sr-section-title">
        <span>Podio</span>
        <strong>${s.nome_breve}</strong>
      </div>

      <div class="sr-podio">
        ${o.length?o.map(r=>{const t=n[r.giocante_id],c=r.posizione===1;return`
              <button class="sr-podio-player ${c?"is-winner":""}" data-player="${t.id}">
                <div class="sr-medal sr-medal-${r.posizione}">${r.posizione}</div>
                ${avatar(t,c?"large":"medium")}
                <h3>${t.nome}</h3>
                <div class="sr-podio-stats">
                  <span><strong>${r.sv}</strong> SV</span>
                  <span><strong>${r.punti}</strong> punti</span>
                  <span><strong>${r.partite_giocate}/${r.partite_totali}</strong> PG</span>
                </div>
              </button>
            `}).join(""):'<p class="sr-empty">Podio non disponibile.</p>'}
      </div>
    </section>
  `}function renderClassifica(s,a,n){return`
    <section class="sr-card">
      <div class="sr-section-title">
        <span>Classifica completa</span>
        <strong>${s.nome_breve}</strong>
      </div>

      <div class="sr-table">
        <div class="sr-row sr-row-head">
          <span>#</span>
          <span>Giocante</span>
          <span>SV</span>
          <span>Punti</span>
          <span>PG</span>
        </div>

        ${a.map(e=>{const o=n[e.giocante_id];return`
            <button class="sr-row sr-player-row" data-player="${o.id}">
              <span class="sr-position">${e.posizione}</span>
              <span class="sr-player-cell">
                ${avatar(o,"small")}
                <strong>${o.nome}</strong>
              </span>
              <span>${e.sv}</span>
              <span>${e.punti}</span>
              <span>${e.partite_giocate}/${e.partite_totali}</span>
            </button>
          `}).join("")}
      </div>
    </section>
  `}function renderPlayerModal(s){const a=document.querySelector(".sr-modal");a&&a.remove();const n=document.createElement("div");n.className="sr-modal",n.innerHTML=`
    <div class="sr-modal-backdrop" data-close-modal></div>

    <article class="sr-modal-content">
      <button class="sr-modal-close" data-close-modal>\xD7</button>

      <div class="sr-player-detail">
        ${avatar(s,"profile")}
        <h2>${s.nome}</h2>

        <div class="sr-player-meta">
          <div>
            <span>Conferenza</span>
            <strong>${s.conferenza}</strong>
          </div>
          <div>
            <span>Squadra</span>
            <strong>${s.squadra}</strong>
          </div>
        </div>

        <blockquote>
          <span>\u201C</span>
          ${s.motto}
          <span>\u201D</span>
        </blockquote>
      </div>
    </article>
  `,document.body.appendChild(n),n.querySelectorAll("[data-close-modal]").forEach(e=>{e.addEventListener("click",()=>n.remove())})}async function showConferenceDetail(s,a,n){a.innerHTML=`
    <div class="sr-loading">
      Caricamento ${s.nome_breve}...
    </div>
  `;try{const{classifica:e,giocantiMap:o}=await loadConferenceData(n,s.id);a.innerHTML=`
      <div class="sr-selected-heading">
        <button class="sr-back-button" type="button" data-back-conferences>\u2190 Conferenze</button>
        <h2>${s.nome_breve}</h2>
      </div>

      ${renderPodio(s,e,o)}
      ${renderClassifica(s,e,o)}
    `,a.querySelectorAll("[data-player]").forEach(r=>{r.addEventListener("click",()=>{renderPlayerModal(o[r.dataset.player])})}),a.querySelector("[data-back-conferences]").addEventListener("click",()=>{a.innerHTML="",window.scrollTo({top:0,behavior:"smooth"})}),a.scrollIntoView({behavior:"smooth",block:"start"})}catch(e){a.innerHTML=`
      <div class="sr-card">
        <p>Impossibile caricare i dati di ${s.nome_breve}.</p>
      </div>
    `,console.error(e)}}async function initStagioneRegolare(){const s=getSeasonBaseFromPage(),a=document.querySelector("#stagione-regolare-app");if(!(!a||!s))try{const e=(await loadJson(`${s}/conferenze.json`)).filter(r=>r.attiva);a.innerHTML=`
      <div id="sr-conference-selector">
        ${await renderConferenceCards(e,s)}
      </div>

      <div id="sr-conference-detail"></div>
    `;const o=a.querySelector("#sr-conference-detail");a.querySelectorAll("[data-conference]").forEach(r=>{r.addEventListener("click",()=>{const t=e.find(c=>c.id===r.dataset.conference);showConferenceDetail(t,o,s)})})}catch(n){a.innerHTML=`
      <div class="sr-card">
        <p>Impossibile caricare i dati della stagione regolare.</p>
      </div>
    `,console.error(n)}}document.addEventListener("DOMContentLoaded",initStagioneRegolare);
